DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='orgmap_app') THEN CREATE ROLE orgmap_app LOGIN PASSWORD 'orgmap_app_local_only' NOSUPERUSER NOBYPASSRLS; END IF; END $$;
CREATE TABLE accounts(id uuid PRIMARY KEY,email text NOT NULL UNIQUE,display_name text NOT NULL,password_hash text NOT NULL);
CREATE TABLE sessions(token_hash text PRIMARY KEY,account_id uuid NOT NULL REFERENCES accounts(id),csrf text NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE organizations(id uuid PRIMARY KEY,name text NOT NULL,locale text NOT NULL,time_zone text NOT NULL,version int NOT NULL DEFAULT 1,structure_revision int NOT NULL DEFAULT 1,authorization_revision int NOT NULL DEFAULT 1);
CREATE TABLE members(organization_id uuid NOT NULL REFERENCES organizations(id),id uuid NOT NULL,account_id uuid NOT NULL REFERENCES accounts(id),org_role text NOT NULL CHECK(org_role IN ('OWNER','MEMBER')),status text NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','SUSPENDED')),version int NOT NULL DEFAULT 1,PRIMARY KEY(organization_id,id),UNIQUE(organization_id,account_id));
CREATE TABLE entities(organization_id uuid NOT NULL REFERENCES organizations(id),id uuid NOT NULL,node_id uuid NOT NULL UNIQUE,kind text NOT NULL CHECK(kind IN ('CIRCLE','ROLE')),parent_id uuid,name text NOT NULL,purpose text NOT NULL DEFAULT '',archived boolean NOT NULL DEFAULT false,version int NOT NULL DEFAULT 1,PRIMARY KEY(organization_id,id),FOREIGN KEY(organization_id,parent_id) REFERENCES entities(organization_id,id));
CREATE UNIQUE INDEX single_root ON entities(organization_id) WHERE parent_id IS NULL;
CREATE TABLE circle_memberships(organization_id uuid NOT NULL,id uuid NOT NULL,member_id uuid NOT NULL,circle_id uuid NOT NULL,starts_at timestamptz NOT NULL,ends_at timestamptz,PRIMARY KEY(organization_id,id),FOREIGN KEY(organization_id,member_id) REFERENCES members(organization_id,id),FOREIGN KEY(organization_id,circle_id) REFERENCES entities(organization_id,id),CHECK(ends_at IS NULL OR ends_at>starts_at));
CREATE TABLE occupancies(organization_id uuid NOT NULL,id uuid NOT NULL,member_id uuid NOT NULL,role_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN ('DIRECT','INTERIM')),scope text NOT NULL DEFAULT '',starts_at timestamptz NOT NULL,ends_at timestamptz,version int NOT NULL DEFAULT 1,PRIMARY KEY(organization_id,id),FOREIGN KEY(organization_id,member_id) REFERENCES members(organization_id,id),FOREIGN KEY(organization_id,role_id) REFERENCES entities(organization_id,id),CHECK(ends_at IS NULL OR ends_at>starts_at),CHECK(kind<>'INTERIM' OR ends_at IS NOT NULL));
CREATE TABLE audit_events(organization_id uuid NOT NULL,id uuid NOT NULL,actor_id uuid NOT NULL,resource_id uuid NOT NULL,action text NOT NULL,at timestamptz NOT NULL DEFAULT now(),request_id text NOT NULL,PRIMARY KEY(organization_id,id));
CREATE TABLE domain_events(organization_id uuid NOT NULL,id uuid NOT NULL,action text NOT NULL,resource_id uuid NOT NULL,at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(organization_id,id));
CREATE TABLE outbox(organization_id uuid NOT NULL,id uuid NOT NULL,event_id uuid NOT NULL,state text NOT NULL DEFAULT 'PENDING',PRIMARY KEY(organization_id,id),FOREIGN KEY(organization_id,event_id) REFERENCES domain_events(organization_id,id));
CREATE TABLE command_results(organization_id uuid NOT NULL,actor_id uuid NOT NULL,operation text NOT NULL,key text NOT NULL,hash text NOT NULL,result jsonb NOT NULL,PRIMARY KEY(organization_id,actor_id,operation,key));
CREATE TABLE account_commands(account_id uuid NOT NULL REFERENCES accounts(id),key text NOT NULL,hash text NOT NULL,result jsonb NOT NULL,PRIMARY KEY(account_id,key));
GRANT USAGE ON SCHEMA public TO orgmap_app;
GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA public TO orgmap_app;
